      {
        rel: "stylesheet",
        href: "https://fonts.googleapis.com/css2?family=Orbitron:wght@500;700&family=Rajdhani:wght@400;500;600&display=swap",
      },
      {
        rel: "stylesheet",
        href: appCss,
      },
      { rel: "icon", href: "/favicon.ico", type: "image/x-icon" },
    ],
  }),
  shellComponent: RootShell,
  component: RootComponent,
  notFoundComponent: NotFoundComponent,
  errorComponent: ErrorComponent,
});

function RootShell({ children }: { children: ReactNode }) {
  return (
    <html lang="pt-BR">
      <head>
        <HeadContent />
      </head>
      <body>
        {children}
        <Scripts />
      </body>
    </html>
  );
}

function RootComponent() {
  const { queryClient } = Route.useRouteContext();
  const router = useRouter();
  const [auth, setAuth] = useState<AuthState>({user:null,ready:false});
  useEffect(() => {
    return observeAuth(() => supabase.auth, setAuth, (event) => {
      if (["SIGNED_IN","SIGNED_OUT","USER_UPDATED"].includes(event)) {
        void router.invalidate();
        if(event !== "SIGNED_OUT") void queryClient.invalidateQueries();
      }
    });
  }, [queryClient, router]);

  return (
    <QueryClientProvider client={queryClient}>
      {/* Required: nested routes render here. Removing <Outlet /> breaks all child routes. */}
      <JarvisAuthProvider value={auth}><Outlet /></JarvisAuthProvider>
    </QueryClientProvider>
  );
}

